using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-62c99c673e0540b9b57115245e8a8fa2/build.binlog");

// Check if Api had its own compile errors or just cascaded
Console.WriteLine("=== ALL ERRORS WITH FULL CONTEXT ===");
build.VisitAllChildren<Error>(error =>
{
    // Walk up to find the owning project
    var node = error.Parent;
    string projectPath = "";
    while (node != null)
    {
        if (node is Project p)
        {
            projectPath = p.ProjectFile ?? p.Name;
            break;
        }
        node = (node as TreeNode)?.Parent;
    }
    Console.WriteLine($"Project: {projectPath}");
    Console.WriteLine($"  [{error.Code}] {error.File}:{error.LineNumber}");
    Console.WriteLine($"  {error.Text}");
    Console.WriteLine();
});

// Check for MSB3202 (project dependency not found) or similar
Console.WriteLine("=== MSB WARNINGS/ERRORS ===");
build.VisitAllChildren<Warning>(w =>
{
    if (w.Code != null && (w.Code.StartsWith("MSB") || w.Code.StartsWith("NU")))
    {
        if (w.Code == "MSB3270" || w.Code == "MSB3202" || w.Code == "MSB3644" || w.Code.StartsWith("NU1"))
            Console.WriteLine($"[{w.Code}] {w.Text}");
    }
});
